<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">node.roles: [</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">data_hot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">data_content</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
